331	    /**
332	     * Emits the audit trail for a freshly created owner: the human-readable {@code AUDIT} line and the
333	     * structured {@link OwnerCreatedEvent}, in that order. Both carry the owner's primary identifier,
334	     * the unified {@code memberId} returned by {@link #primaryIdentifier}, so keeping the two emissions
335	     * together in one place lets the audit trail's view of the owner's identity change in a single spot.
336	     * The event's {@code seq} is bumped exactly once here, so every emitted event carries a strictly
337	     * larger sequence number than the create before it.
338	     *
339	     * @param owner    the freshly created and persisted owner, already stamped with its identity
340	     * @param ownerDto the owner's mapped DTO, the source of the derived {@code membershipLevel} carried
341	     *                 on the audit trail
342	     */
343	    private void emitOwnerCreatedAudit(Owner owner, OwnerDto ownerDto) {
344	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
345	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
346	            ownerDto.getMembershipLevel());
347	        AUDIT.info(ownerCreatedEvent(owner, ownerDto).toJson());
348	    }
349	
350	    /**
351	     * Builds the structured {@link OwnerCreatedEvent} published for a freshly created owner. The
352	     * event's payload is composed here in one place: its {@code seq} by bumping {@link #EVENT_SEQ}
353	     * exactly once, its primary identifier through {@link #primaryIdentifier}, and its
354	     * {@code membershipLevel} from the mapped DTO. Keeping the event's shape behind this single builder
355	     * lets the audit event's payload change in one spot, mirroring {@link #primaryIdentifier}'s single
356	     * accessor for the owner's identity.
357	     *
358	     * @param owner    the freshly created and persisted owner, already stamped with its identity
359	     * @param ownerDto the owner's mapped DTO, the source of the derived {@code membershipLevel} carried
360	     *                 on the event
361	     * @return the structured audit event to publish
362	     */
363	    private OwnerCreatedEvent ownerCreatedEvent(Owner owner, OwnerDto ownerDto) {
364	        return new OwnerCreatedEvent(EVENT_SEQ.incrementAndGet(),
365	            owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel());
366	    }
