371	     * {@code memberId} (routed through {@link #primaryIdentifier}), the two values a downstream
372	     * consumer needs to address the welcome to the new member.
373	     *
374	     * @param owner the freshly created and persisted owner, already stamped with its {@code memberId}
375	     */
376	    private void enqueueWelcomeNotification(Owner owner) {
377	        NOTIFY.info("welcome notification queued ownerId={} memberId={}",
378	            owner.getId(), primaryIdentifier(owner));
379	    }
