393	    /**
394	     * Reads the optional {@code Idempotency-Key} header from the current request. The generated
395	     * {@code addOwner} signature carries only the request body, so the header is pulled from the
396	     * request bound to the current thread. Returns the trimmed key, or {@code null} when the header is
397	     * absent or blank (in which case the create proceeds normally, without idempotent replay).
398	     *
399	     * @return the non-blank idempotency key, or {@code null} when none was supplied
400	     */
401	    private String idempotencyKey() {
402	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
403	            return null;
404	        }
405	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
406	        return isBlank(key) ? null : key.trim();
407	    }
