409	    /**
410	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
411	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
412	     * the request body already rejects null and empty values, but permits whitespace-only strings
413	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
414	     * that gap so every required field must carry a non-blank value.
415	     *
416	     * @param ownerFieldsDto the submitted owner fields
417	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
418	     */
419	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
420	        List<String> missing = new ArrayList<>();
421	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
422	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
423	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
424	            missing.add("address");
425	        }
426	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
427	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
428	        if (!missing.isEmpty()) {
429	            throw new InvalidOwnerFieldsException(missing);
430	        }
431	    }
