433	    /**
434	     * Rejects an owner whose supplied {@code postcode} is invalid for its {@code city}. The postcode is
435	     * optional: when absent (null) the owner is accepted unchanged, so the request contract stays
436	     * backward-compatible. When present it must be four digits and, when the city maps to a known region,
437	     * must fall within that region's fixed inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
438	     * {@code QLD 4000-4099}); a city with no known region accepts any 4-digit postcode. See
439	     * {@link PostcodeValidator}.
440	     *
441	     * @param ownerFieldsDto the submitted owner fields (its {@code city} is non-blank here,
442	     *                       {@link #rejectBlankOwnerFields} having already run)
443	     * @throws InvalidOwnerFieldsException if a postcode is present but not valid for the city
444	     */
445	    private void rejectInvalidPostcode(OwnerFieldsDto ownerFieldsDto) {
446	        if (!PostcodeValidator.isValid(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode())) {
447	            throw new InvalidOwnerFieldsException(List.of("postcode"));
448	        }
449	    }
