451	    private void addIfBlank(List<String> missing, String fieldName, String value) {
452	        if (isBlank(value)) {
453	            missing.add(fieldName);
454	        }
455	    }
456	
457	    private boolean isBlank(String value) {
458	        return value == null || value.isBlank();
459	    }
