461	    /**
462	     * Normalizes the submitted address on create to its canonical form (see
463	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
464	     * stored and returned, and the form every later address comparison (the required-field check,
465	     * household duplicate detection and the shared household id) is judged on. The structured fields
466	     * are preferred: {@code addressLine1} and the optional {@code addressLine2} are each normalized in
467	     * place, and the flat {@code address} is set to the {@linkplain #composedAddress composed} value
468	     * derived from them when a structured {@code addressLine1} is present, falling back to the
469	     * normalized flat {@code address} otherwise. Any absent field is left absent so
470	     * {@link #rejectBlankOwnerFields} still reports a wholly missing address; a value that is blank
471	     * after normalization likewise reduces to the empty string and is rejected there.
472	     *
473	     * @param ownerFieldsDto the submitted owner fields
474	     */
475	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
476	        String addressLine1 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine1());
477	        String addressLine2 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine2());
478	        String flatAddress = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddress());
479	        ownerFieldsDto.setAddressLine1(addressLine1);
480	        ownerFieldsDto.setAddressLine2(addressLine2);
481	        ownerFieldsDto.setAddress(composedAddress(addressLine1, addressLine2, flatAddress));
482	    }
483	
484	    /**
485	     * Composes the flat {@code address} an owner should carry from its (already normalized) address
486	     * fields, preferring the structured form. When a non-blank {@code addressLine1} is present the
487	     * composed address is {@code addressLine1}, with a single space and {@code addressLine2} appended
488	     * when {@code addressLine2} is present; otherwise the flat {@code address} is used unchanged. This
489	     * is the single value every later reader of the address (the required-field check, household
490	     * duplicate detection and the shared household id) is judged on.
491	     *
492	     * @param addressLine1 the normalized first address line, or {@code null}/blank when absent
493	     * @param addressLine2 the normalized second address line, or {@code null}/blank when absent
494	     * @param flatAddress  the normalized flat address, or {@code null}/blank when absent
495	     * @return the composed flat address, or {@code null} when no address form was supplied
496	     */
497	    private String composedAddress(String addressLine1, String addressLine2, String flatAddress) {
498	        if (isBlank(addressLine1)) {
499	            return flatAddress;
500	        }
501	        if (isBlank(addressLine2)) {
502	            return addressLine1;
503	        }
504	        return addressLine1 + " " + addressLine2;
505	    }
506	
507	    /**
508	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
509	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
510	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
511	     * {@code 400 Bad Request}.
512	     *
513	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
514	     *                       {@link #rejectBlankOwnerFields} having already run)
515	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
516	     */
517	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
518	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
519	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
520	        ownerFieldsDto.setTelephone(normalized);
521	    }
522	
523	    /**
524	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
525	     * untouched (email is optional). When present it is reduced to its canonical form (see
526	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
527	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
528	     *
529	     * @param ownerFieldsDto the submitted owner fields
530	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address,
531	     *                                     or its domain is on the disposable-domain blocklist
532	     */
533	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
534	        String email = ownerFieldsDto.getEmail();
535	        if (email == null || email.isBlank()) {
536	            return;
537	        }
538	        String normalized = EmailNormalizer.normalize(email)
539	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
540	        if (EmailNormalizer.hasDisposableDomain(normalized)) {
541	            throw new InvalidOwnerFieldsException(List.of("email"));
542	        }
543	        ownerFieldsDto.setEmail(normalized);
544	    }
