546	    /**
547	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
548	     * duplicate detection is now expressed through the single derived {@code identityKey}
549	     * ({@code sha256hex(normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName))}, see
550	     * {@link OwnerIdentity}), which replaces the previously separate telephone, email and household
551	     * checks. Two owners denote the same person when their whole identity keys are equal, so a create
552	     * is rejected as a {@code 409 Conflict} when another (non-deleted) owner already carries the same
553	     * key. Because the telephone is part of the key, two owners who share a last name and postcode but
554	     * carry different telephones have different keys and are both allowed (they are instead recorded as
555	     * a {@linkplain #findPossibleDuplicate possible duplicate}); an email or a household on its own no
556	     * longer makes a duplicate.
557	     *
558	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
559	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
560	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
561	     */
562	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
563	        String identityKey = OwnerIdentity.identityKey(
564	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
565	        boolean inUse = activeOwners().stream()
566	            .map(OwnerIdentity::identityKey)
567	            .anyMatch(identityKey::equals);
568	        if (inUse) {
569	            throw new DuplicateOwnerIdentityException(identityKey);
570	        }
571	    }
572	
573	    /**
574	     * The owners considered by duplicate detection: every persisted owner except those flagged
575	     * {@code deleted}. A soft-deleted owner is retained but must never make a later create look like a
576	     * duplicate, so both the hard-duplicate identity check ({@link #rejectDuplicateIdentity}) and the
577	     * soft {@linkplain #findPossibleDuplicate possible-duplicate} match are judged against these owners
578	     * alone. Only owners already persisted (before this create) are included.
579	     *
580	     * @return the non-deleted owners currently persisted
581	     */
582	    private List<Owner> activeOwners() {
583	        return this.clinicService.findAllOwners().stream()
584	            .filter(owner -> !owner.isDeleted())
585	            .toList();
586	    }
587	
588	    /**
589	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
590	     * both match the submitted values, compared case-insensitively. The count reflects only owners
591	     * already persisted at the time of the create, so the owner being created is never included.
592	     *
593	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
594	     *                  having already run)
595	     * @param lastName  the submitted last name (non-blank here)
596	     * @return the number of existing owners sharing the same first and last name
597	     */
598	    private int countNamesakes(String firstName, String lastName) {
599	        return (int) this.clinicService.findAllOwners().stream()
600	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
601	                && lastName.equalsIgnoreCase(owner.getLastName()))
602	            .count();
603	    }
604	
605	    /**
606	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
607	     * whose stored {@code householdId} equals the value derived for the owner being created. The
608	     * count reflects only owners already persisted at the time of the create, so the owner being
609	     * created is never included; callers add one to obtain the household size after this create.
610	     *
611	     * @param householdId the household identifier derived for the owner being created (see
612	     *                    {@link HouseholdNormalizer#toHouseholdId})
613	     * @return the number of existing owners already sharing that household
614	     */
615	    private int countHouseholdMembers(String householdId) {
616	        return householdMembers(householdId).size();
617	    }
618	
619	    /**
620	     * Returns the existing owners (before this create) belonging to the given household, i.e. those
621	     * whose stored {@code householdId} equals the value derived for the owner being created. As with
622	     * {@link #countHouseholdMembers}, only owners already persisted are included, so the owner being
623	     * created is never among them.
624	     *
625	     * @param householdId the household identifier derived for the owner being created (see
626	     *                    {@link HouseholdNormalizer#toHouseholdId})
627	     * @return the existing owners already sharing that household (empty when {@code householdId} is
628	     *         {@code null})
629	     */
630	    private List<Owner> householdMembers(String householdId) {
631	        if (householdId == null) {
632	            return List.of();
633	        }
634	        return this.clinicService.findAllOwners().stream()
635	            .filter(member -> householdId.equals(member.getHouseholdId()))
636	            .toList();
637	    }
638	
639	    /**
640	     * Caps a new owner's {@code membershipLevel} so it cannot exceed one above the current maximum
641	     * {@code membershipLevel} among their existing household members. The owner's own level is the
642	     * value {@linkplain OwnerMapper#membershipLevel(Owner) it would otherwise report}; it is capped at
643	     * {@code maxHouseholdLevel + 1}. When the household has no existing member no cap applies and the
644	     * owner's own level is returned unchanged.
645	     *
646	     * @param owner the owner being created, already stamped with its household id and size
647	     * @return the (possibly capped) membership level to stamp on the owner
648	     */
649	    private int cappedMembershipLevel(Owner owner) {
650	        int ownLevel = this.ownerMapper.membershipLevel(owner);
651	        OptionalInt maxHouseholdLevel = householdMembers(owner.getHouseholdId()).stream()
652	            .mapToInt(this.ownerMapper::membershipLevel)
653	            .max();
654	        return maxHouseholdLevel.isPresent()
655	            ? Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1)
656	            : ownLevel;
657	    }
658	
659	    /**
660	     * Derives the address an owner should carry from its submitted fields. The update path stamps an
661	     * owner with an address taken from the request, so routing that through this single method keeps the
662	     * derivation of "the owner's address" in one place, mirroring {@link #householdIdFor} for the
663	     * household id.
664	     *
665	     * @param ownerFieldsDto the submitted owner fields
666	     * @return the address to store on the owner
667	     */
668	    private String addressFor(OwnerFieldsDto ownerFieldsDto) {
669	        return ownerFieldsDto.getAddress();
670	    }
671	
672	    /**
673	     * Derives the household id an owner should carry from its submitted fields (see
674	     * {@link HouseholdNormalizer#toHouseholdId}). Both create and update stamp an owner with a
675	     * household id, so routing them through this single method keeps them agreed on which of the
676	     * owner's fields key the household.
677	     *
678	     * @param ownerFieldsDto the submitted owner fields (its identifying fields are non-blank here,
679	     *                       {@link #rejectBlankOwnerFields} having already run on create)
680	     * @return the owner's household id
681	     */
682	    private String householdIdFor(OwnerFieldsDto ownerFieldsDto) {
683	        return HouseholdNormalizer.toHouseholdId(
684	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
685	    }
686	
687	    /**
688	     * Finds an existing owner that the owner being created soft-matches on, or {@code null} when there
689	     * is none. The create has already cleared the hard-duplicate identity check
690	     * ({@link #rejectDuplicateIdentity}), so its {@code identityKey} matches no existing owner; it is a
691	     * <em>possible</em> duplicate when it nevertheless shares an existing owner's {@code postcode} and
692	     * the {@linkplain Soundex#soundex Soundex} of its {@code lastName} while their identity keys still
693	     * differ. Because the telephone is part of the identity key, two owners with the same last name and
694	     * postcode but different telephones have differing keys and so soft-match here rather than colliding
695	     * as a hard duplicate. The oldest such owner (the earliest persisted) is returned so the flag points
696	     * at the original record; owners with no postcode never match, since a shared postcode is required.
697	     *
698	     * @param owner the owner being created, with telephone already normalized and lastName/postcode set
699	     * @return the id of the matching existing owner, or {@code null} when the owner is not a possible
700	     *         duplicate
701	     */
702	    private Integer findPossibleDuplicate(Owner owner) {
703	        String postcode = owner.getPostcode();
704	        if (postcode == null) {
705	            return null;
706	        }
707	        String identityKey = OwnerIdentity.identityKey(owner);
708	        String lastNameCode = Soundex.soundex(owner.getLastName());
709	        return activeOwners().stream()
710	            .filter(existing -> !identityKey.equals(OwnerIdentity.identityKey(existing)))
711	            .filter(existing -> lastNameCode.equals(Soundex.soundex(existing.getLastName())))
712	            .filter(existing -> postcode.equals(existing.getPostcode()))
713	            .map(Owner::getId)
714	            .filter(Objects::nonNull)
715	            .min(Integer::compareTo)
716	            .orElse(null);
717	    }
718	
719	    /**
720	     * Records on the owner being created whether it is a possible (soft) duplicate of an existing
721	     * owner. The match itself is decided by {@link #findPossibleDuplicate}; this method reflects its
722	     * result into the two stored fields, so the interpretation of "is a possible duplicate" lives in
723	     * one place: {@code possibleDuplicateOf} holds the matched owner's id (or {@code null} when there
724	     * is none) and {@code possibleDuplicate} is {@code true} exactly when a match was found. An owner
725	     * that opted in with {@code sharesHousehold} is a declared household member, not a suspected
726	     * duplicate, so it is never flagged.
727	     *
728	     * @param owner           the owner being created, with telephone already normalized and
729	     *                        lastName/postcode set
730	     * @param sharesHousehold whether the request opted in to sharing a household
731	     */
732	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
733	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
734	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
735	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
736	    }
737	
738	    /**
739	     * Counts how many existing owners already live in the given city. The submitted city is compared
740	     * case-insensitively against every existing owner's stored city. The result drives both the hard
741	     * capacity rejection (see {@link #rejectCityAtCapacity}) and the {@code capacityWarning} flag.
742	     *
743	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
744	     *             run)
745	     * @return the number of existing owners whose city matches the submitted city
746	     */
747	    private long countOwnersInCity(String city) {
748	        return this.clinicService.findAllOwners().stream()
749	            .map(Owner::getCity)
750	            .filter(Objects::nonNull)
751	            .filter(city::equalsIgnoreCase)
752	            .count();
753	    }
754	
755	    /**
756	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
757	     * A city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
758	     *
759	     * @param city         the submitted city (used only to report the conflict)
760	     * @param ownersInCity the number of owners the city already holds (see {@link #countOwnersInCity})
761	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
762	     */
763	    private void rejectCityAtCapacity(String city, long ownersInCity) {
764	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
765	            throw new OwnerCityAtCapacityException(city);
766	        }
767	    }
768	
769	    /**
770	     * Resolves the effective registration date for a create, rolled onto a business day. The
771	     * supplied date is used when present, otherwise the server's current date; either way the result
772	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
773	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
774	     * stored {@code registrationDate}, the membership number's year segment and the daily
775	     * create-limit's per-day count - is judged on this adjusted date.
776	     *
777	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
778	     *                                 default to the server's current date
779	     * @return the effective registration date, guaranteed to fall on a business day
780	     */
781	    /**
782	     * Rejects a create whose supplied {@code registrationDate} lies after the server's current date.
783	     * The raw submitted value is compared against {@link LocalDate#now()} before any business-day
784	     * adjustment; a future date cannot describe a registration that has already happened, so it is
785	     * reported as a {@code 400 Bad Request}. A {@code null} registration date (defaulted to the
786	     * server's current date) and any date on or before today are accepted.
787	     *
788	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when
789	     *                                 omitted
790	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server's current date
791	     */
792	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
793	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
794	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
795	        }
796	    }
797	
798	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
799	        LocalDate registrationDate =
800	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
801	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
802	    }
803	
804	    /**
805	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
806	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
807	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
808	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
809	     * Too Many Requests}.
810	     *
811	     * @param registrationDate   the create's effective registration date, already rolled onto a
812	     *                           business day by {@link #effectiveRegistrationDate}
813	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
814	     *                           {@code registrationDate} equals {@code registrationDate}
815	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
816	     *                                              owner registrations
817	     */
818	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
819	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
820	            throw new OwnerDailyRegistrationLimitException(registrationDate);
821	        }
822	    }
823	
824	    /**
825	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
826	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
827	     * bulk-signup warning are judged on.
828	     *
829	     * @param registrationDate the create's effective registration date, already rolled onto a business
830	     *                         day by {@link #effectiveRegistrationDate}
831	     * @return the number of existing owners registered on that day
832	     */
833	    private long countRegisteredOn(LocalDate registrationDate) {
834	        return this.clinicService.findAllOwners().stream()
835	            .map(Owner::getRegistrationDate)
836	            .filter(registrationDate::equals)
837	            .count();
838	    }
839	}
